export type BatteryChemistry = 'liion' | 'lifepo4' | 'lic';

export type BatteryChargerMode = 'none' | 'unplugged' | 'charging' | 'charged' | 'no_cell' | 'fault';

export type BatteryCellLevel = 'ok' | 'low' | 'critical' | 'empty';

export type BatteryProtectReason = 'floor' | 'ceiling';

/** fr.battery.read RESULT fields. */
export interface BatteryReadResult {
  /** (mV) */
  mv: number;
  /** at the pin, before the divider (mV) */
  adcMv: number;
  percent: number;
  charger: BatteryChargerMode | number;
  level: BatteryCellLevel | number;
  dividerMilli: number;
  calibrated: boolean;
  load: boolean;
  gate: boolean;
  injected: boolean;
}

/** fr.battery.calibrate arguments (all optional: the device applies the defaults). */
export interface BatteryCalibrateArgs {
  /** (mV) */
  meterMv?: number;
}

/** fr.battery.calibrate RESULT fields. */
export interface BatteryCalibrateResult {
  dividerMilli: number;
  /** (mV) */
  adcMv: number;
}

/** fr.battery.load arguments (all optional: the device applies the defaults). */
export interface BatteryLoadArgs {
  on?: boolean;
  /** (s; 0..86400) */
  seconds?: number;
}

/** fr.battery.gate arguments (all optional: the device applies the defaults). */
export interface BatteryGateArgs {
  open?: boolean;
}

/** fr.battery commands, as methods of an instance. */
export interface BatteryClient {
  /** The last sample and the calibration in use. Never touches the ADC. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  read(opts?: CallOptions): Promise<CmdResult<BatteryReadResult>>;
  /** The divider becomes meter_mv / adc_mv (a multimeter on the cell), kept across reboots. BUSY with no sample yet; INVALID_ARGS when the result is more than 15 % from config divider_milli (a typo in the reading). Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  calibrate(args?: BatteryCalibrateArgs, opts?: CallOptions): Promise<CmdResult<BatteryCalibrateResult>>;
  /** Config divider_milli again; the kept calibration is erased. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  resetCalibration(opts?: CallOptions): Promise<CmdResult>;
  /** The test load on for at most `seconds` (0 means 60), or off; while it is on, `on` renews its time at any level above empty. It also goes off at the floor, on a stale reading, at boot, and 60 s after the newest frame of the hub that turned it on (or at a new hub run). UNSUPPORTED without a load; BUSY turning it on at or below critical. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  load(args?: BatteryLoadArgs, opts?: CallOptions): Promise<CmdResult>;
  /** Opens or closes the charge gate by hand. An open gate still closes at charge_to_mv; a hand close stands until the charger's state changes. UNSUPPORTED without a gate; BUSY opening it at or above charge_to_mv. Reliable: resolves on the RESULT ok, rejects with CommandError otherwise. */
  gate(args?: BatteryGateArgs, opts?: CallOptions): Promise<CmdResult>;
}

/** fr.battery.charge event fields (normal). The charger's state changed (held 300 ms before it counts). */
export interface BatteryChargeFields {
  state: BatteryChargerMode | number;
  /** (mV) */
  mv: number;
}

/** fr.battery.level_change event fields (normal). The level changed (low, critical, empty, or back to ok). */
export interface BatteryLevelChangeFields {
  level: BatteryCellLevel | number;
  /** (mV) */
  mv: number;
}

/** fr.battery.protect event fields (realtime). The node cut loads at the floor (floor) or closed the gate above full (ceiling) on its own. */
export interface BatteryProtectFields {
  reason: BatteryProtectReason | number;
  /** (mV) */
  mv: number;
}

/** fr.battery events by wire name: `pad.on('<inst>.<event>', e => ...)`. */
export interface BatteryEvents {
  charge: BatteryChargeFields;
  level_change: BatteryLevelChangeFields;
  protect: BatteryProtectFields;
}

/** fr.battery properties as the mirror holds them (`pad.<inst>.state`); a property a trait gates may be absent. */
export interface BatteryState {
  /** calibrated, 8 conversions, EMA 1/4 (mV) */
  mv: number;
  /** from the chemistry's table (the hub refines it from a cell's learned curve) */
  percent: number;
  charger: BatteryChargerMode | number;
  /** 50 mV hysteresis upward */
  level: BatteryCellLevel | number;
  /** the test load is on */
  loadOn: boolean;
  /** the charge gate is open */
  gateOpen: boolean;
}

/** fr.battery property values by wire name: what a `<inst>.<prop>` event carries as `value`. */
export interface BatteryProps {
  mv: number;
  percent: number;
  charger: BatteryChargerMode | number;
  level: BatteryCellLevel | number;
  load_on: boolean;
  gate_open: boolean;
}

